export const SIDES = ['front','rear','left','right'];
export const normalizeAngle=n=>{const r=n%360;return r<0?r+360:r;};
export const size=i=>{const a=i.rotation*Math.PI/180,c=Math.abs(Math.cos(a)),s=Math.abs(Math.sin(a));return [i.width*c+i.length*s,i.width*s+i.length*c].map(n=>Math.round(n*1e12)/1e12);};
export function itemPoints(i,withBuffer=false){const [w,h]=size(i),cx=i.x+w/2,cy=i.y+h/2,b=withBuffer?getBuffers(i):{left:0,right:0,front:0,rear:0},a=i.rotation*Math.PI/180,c=Math.cos(a),s=Math.sin(a);return (i.category==='area'&&i.vertices&&!withBuffer?i.vertices.map(([x,y])=>[(x-.5)*i.width,(y-.5)*i.length]):[[-i.width/2-b.left,-i.length/2-b.front],[i.width/2+b.right,-i.length/2-b.front],[i.width/2+b.right,i.length/2+b.rear],[-i.width/2-b.left,i.length/2+b.rear]]).map(([x,y])=>[cx+x*c-y*s,cy+x*s+y*c]);}
export function rotateItem(i,angle){const [w,h]=size(i),cx=i.x+w/2,cy=i.y+h/2;i.rotation=normalizeAngle(angle);const [nw,nh]=size(i);i.x=cx-nw/2;i.y=cy-nh/2;}
export function polygonBounds(points){const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);return {x:Math.min(...xs),y:Math.min(...ys),w:Math.max(...xs)-Math.min(...xs),h:Math.max(...ys)-Math.min(...ys)};}
export function getBuffers(item){return item.buffers?{...item.buffers}:Object.fromEntries(SIDES.map(side=>[side,item.buffer??0]));}
export function setBuffers(item,patch){item.buffers={...getBuffers(item),...patch};const v=SIDES.map(s=>item.buffers[s]);item.buffer=v.every(n=>n===v[0])?v[0]:0;}
export function worldBuffers(item){const b=getBuffers(item);switch(item.rotation){case 90:return {top:b.left,right:b.front,bottom:b.right,left:b.rear};case 180:return {top:b.rear,right:b.left,bottom:b.front,left:b.right};case 270:return {top:b.right,right:b.rear,bottom:b.left,left:b.front};default:return {top:b.front,right:b.right,bottom:b.rear,left:b.left};}}
export function bounds(item,buffer=0){const [w,h]=size(item);return {x:item.x-buffer,y:item.y-buffer,w:w+2*buffer,h:h+2*buffer};}
export function bufferBounds(i){return Object.fromEntries(Object.entries(polygonBounds(itemPoints(i,true))).map(([k,v])=>[k,Math.round(v*1e12)/1e12]));}
export function intersects(a,b){return a.x < b.x+b.w-0.001 && a.x+a.w>b.x+0.001 && a.y<b.y+b.h-0.001 && a.y+a.h>b.y+0.001;}
export function roomPoints(r){return r.shape==='l'?[[0,0],[r.width,0],[r.width,r.upperLength],[r.innerWidth,r.upperLength],[r.innerWidth,r.length],[0,r.length]]:[[0,0],[r.width,0],[r.width,r.length],[0,r.length]];}
export function roomArea(r){return r.width*r.length-(r.shape==='l'?(r.width-r.innerWidth)*(r.length-r.upperLength):0);}
export function wallPoints(w){const dx=w.x2-w.x1,dy=w.y2-w.y1,len=Math.hypot(dx,dy),nx=-dy/len*w.thickness/2,ny=dx/len*w.thickness/2;return [[w.x1+nx,w.y1+ny],[w.x2+nx,w.y2+ny],[w.x2-nx,w.y2-ny],[w.x1-nx,w.y1-ny]];}
function convexOverlap(a,b){for(const polygon of [a,b])for(let j=0;j<polygon.length;j++){const p=polygon[j],q=polygon[(j+1)%polygon.length],axis=[-(q[1]-p[1]),q[0]-p[0]],alen=Math.hypot(...axis);if(!alen)continue;const project=points=>points.map(v=>(v[0]*axis[0]+v[1]*axis[1])/alen),aa=project(a),bb=project(b);if(Math.max(...aa)<=Math.min(...bb)+.001||Math.max(...bb)<=Math.min(...aa)+.001)return false;}return true;}
const rectPoints=b=>[[b.x,b.y],[b.x+b.w,b.y],[b.x+b.w,b.y+b.h],[b.x,b.y+b.h]];
function outsidePolygon(poly,room){const b=polygonBounds(poly);if(b.x<-.001||b.y<-.001||b.x+b.w>room.width+.001||b.y+b.h>room.length+.001)return true;return room.shape==='l'&&polygonOverlap(poly,rectPoints({x:room.innerWidth,y:room.upperLength,w:room.width-room.innerWidth,h:room.length-room.upperLength}));}
export function inspect(items,room){const result=new Map(items.map(i=>[i.id,[]]));for(let a=0;a<items.length;a++){const i=items[a];if(i.category==='area'||i.storedIn)continue;const poly=itemPoints(i),buffer=itemPoints(i,true);if(outsidePolygon(poly,room))result.get(i.id).push('Outside room');else if(outsidePolygon(buffer,room))result.get(i.id).push('Planning buffer outside room');for(const wall of room.walls||[]){if(polygonOverlap(poly,wallPoints(wall)))result.get(i.id).push('Wall conflict');else if(polygonOverlap(buffer,wallPoints(wall)))result.get(i.id).push('Planning buffer at wall');}for(const area of items.filter(o=>o.category==='area'&&o.placement==='keep-clear'))if(i.category!=='obstacle'&&polygonOverlap(poly,itemPoints(area)))result.get(i.id).push('Equipment in keep-clear area: '+area.name);for(let j=a+1;j<items.length;j++){const other=items[j];if(other.category==='area'||other.storedIn)continue;if(polygonOverlap(poly,itemPoints(other))){result.get(i.id).push('Footprint overlap');result.get(other.id).push('Footprint overlap');}else if(polygonOverlap(buffer,itemPoints(other))||polygonOverlap(itemPoints(other,true),poly)){result.get(i.id).push('Planning buffer conflict');result.get(other.id).push('Planning buffer conflict');}}}return result;}
export function validateProject(p){if(!p||![1,2].includes(p.version)||!Array.isArray(p.layouts)||!p.layouts.length||p.layouts.length>100)throw Error('Choose a Gym Layout Studio JSON export.');const ids=new Set();for(const l of p.layouts){if(typeof l.id!=='string'||ids.has(l.id)||typeof l.name!=='string'||l.name.length>100)throw Error('Invalid layout.');ids.add(l.id);if(!l.room||![l.room.width,l.room.length].every(v=>Number.isFinite(v)&&v>=5&&v<=500))throw Error('Room dimensions must be between 5 and 500 ft.');validateRoomGeometry(l.room);if(!Array.isArray(l.items)||l.items.length>1000)throw Error('Invalid equipment list.');const itemIds=new Set();for(const i of l.items){if(typeof i.id!=='string'||itemIds.has(i.id)||typeof i.name!=='string'||i.name.length>100||!['cardio','strength','free','obstacle','area'].includes(i.category)||!['treadmill','elliptical','bike','rack','bench','cable','column','custom','area'].includes(i.kind))throw Error('Invalid equipment.');itemIds.add(i.id);if(i.vertices!==undefined&&(!simplePolygon(i.vertices)||!i.vertices.every(v=>v.every(n=>n>=0&&n<=1))))throw Error('Area corners must form a simple polygon.');if(i.label!==undefined&&(!i.label||![i.label.x,i.label.y,i.label.rotation].every(Number.isFinite)||i.label.x<0||i.label.x>1||i.label.y<0||i.label.y>1||Math.abs(i.label.rotation)>360))throw Error('Invalid area label.');if((i.storageX!==undefined&&(!Number.isFinite(i.storageX)||Math.abs(i.storageX)>10000))||(i.storageY!==undefined&&(!Number.isFinite(i.storageY)||Math.abs(i.storageY)>10000)))throw Error('Invalid storage position.');if(i.storedIn!==undefined&&typeof i.storedIn!=='string')throw Error('Invalid storage assignment.');if(![i.x,i.y,i.width,i.length,i.rotation].every(Number.isFinite)||i.width<=0||i.length<=0||i.width>100||i.length>100||Math.abs(i.x)>1000||Math.abs(i.y)>1000||i.rotation<0||i.rotation>=360||typeof i.locked!=='boolean')throw Error('Invalid equipment dimensions.');if(i.category==='area'&&(!/^#[0-9a-f]{6}$/i.test(i.color)||!['allowed','keep-clear'].includes(i.placement)))throw Error('Invalid area color or placement rule.');if(i.buffer!==undefined&&(!Number.isFinite(i.buffer)||i.buffer<0||i.buffer>20))throw Error('Invalid planning buffer.');if(i.buffers!==undefined){if(!i.buffers||typeof i.buffers!=='object'||Array.isArray(i.buffers)||!SIDES.every(s=>Number.isFinite(i.buffers[s])&&i.buffers[s]>=0&&i.buffers[s]<=20))throw Error('Each planning buffer must be between 0 and 20 ft.');}else if(!Number.isFinite(i.buffer))throw Error('Missing planning buffers.');}}
for(const l of p.layouts)for(const i of l.items)if(i.storedIn&&i.storedIn!=='@storage'&&!l.items.some(a=>a.id===i.storedIn&&a.category==='area'&&a.storage))throw Error('Missing storage area.');if(p.library!==undefined){if(!Array.isArray(p.library)||p.library.length>300)throw Error('Invalid saved equipment library.');const seen=new Set();for(const t of p.library){if(!t||typeof t.id!=='string'||seen.has(t.id)||typeof t.name!=='string'||!t.name.trim()||t.name.length>100||!['cardio','strength','free'].includes(t.category)||!['treadmill','elliptical','bike','rack','bench','cable','custom'].includes(t.kind)||![t.width,t.length,t.rotation].every(Number.isFinite)||t.width<=0||t.width>100||t.length<=0||t.length>100||t.rotation<0||t.rotation>=360||!SIDES.every(k=>Number.isFinite(getBuffers(t)[k])&&getBuffers(t)[k]>=0&&getBuffers(t)[k]<=20))throw Error('Invalid saved equipment template.');seen.add(t.id);}}if(!ids.has(p.active))throw Error('Invalid active layout.');return {...p,version:2,layouts:p.layouts.map(l=>({...l,items:l.items.map(i=>{const copy={...i};setBuffers(copy,getBuffers(i));return copy;})}))};}

export function validateRoomGeometry(r){if(r.shape!==undefined&&!['rect','l'].includes(r.shape))throw Error('Invalid room shape.');if(r.shape==='l'&&(![r.innerWidth,r.upperLength].every(Number.isFinite)||r.innerWidth<=0||r.innerWidth>=r.width||r.upperLength<=0||r.upperLength>=r.length))throw Error('L-shaped room dimensions must fit inside the overall room.');if(r.walls!==undefined){if(!Array.isArray(r.walls)||r.walls.length>100)throw Error('Invalid walls.');for(const w of r.walls)if(!w||typeof w.name!=='string'||w.name.length>100||!['full','half'].includes(w.type)||![w.x1,w.y1,w.x2,w.y2,w.thickness].every(Number.isFinite)||[w.x1,w.y1,w.x2,w.y2].some(v=>v<0||v>500)||w.thickness<=0||w.thickness>10||Math.hypot(w.x2-w.x1,w.y2-w.y1)<.01)throw Error('Invalid wall segment.');}if(r.zones!==undefined){if(!Array.isArray(r.zones)||r.zones.length>100)throw Error('Invalid zones.');for(const z of r.zones)if(!z||typeof z.name!=='string'||z.name.length>100||![z.x,z.y].every(Number.isFinite)||Math.abs(z.x)>500||Math.abs(z.y)>500||z.angle!==undefined&&(!Number.isFinite(z.angle)||Math.abs(z.angle)>360))throw Error('Invalid zone.');}if(r.walkway!==undefined&&(!Array.isArray(r.walkway)||r.walkway.length<3||r.walkway.length>100||!r.walkway.every(p=>Array.isArray(p)&&p.length===2&&p.every(v=>Number.isFinite(v)&&v>=0&&v<=500))))throw Error('Invalid walkway.');}

export function pointInside(p,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])inside=!inside;}return inside;}
const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);
export function simplePolygon(p){if(!Array.isArray(p)||p.length<3||p.length>60||!p.every(v=>Array.isArray(v)&&v.length===2&&v.every(Number.isFinite)))return false;let area=0;for(let i=0;i<p.length;i++){const a=p[i],b=p[(i+1)%p.length];if(Math.hypot(a[0]-b[0],a[1]-b[1])<1e-6)return false;area+=a[0]*b[1]-a[1]*b[0];for(let j=i+2;j<p.length;j++){if((j+1)%p.length===i)continue;const c=p[j],d=p[(j+1)%p.length];if(cross(a,b,c)*cross(a,b,d)<=0&&cross(c,d,a)*cross(c,d,b)<=0&&Math.max(Math.min(a[0],b[0]),Math.min(c[0],d[0]))<=Math.min(Math.max(a[0],b[0]),Math.max(c[0],d[0]))&&Math.max(Math.min(a[1],b[1]),Math.min(c[1],d[1]))<=Math.min(Math.max(a[1],b[1]),Math.max(c[1],d[1])))return false;}}return Math.abs(area)>1e-8;}
function triangles(poly){let p=poly.map(v=>[...v]),area=p.reduce((s,a,i)=>s+a[0]*p[(i+1)%p.length][1]-a[1]*p[(i+1)%p.length][0],0);if(area<0)p.reverse();const out=[];while(p.length>3){let found=false;for(let i=0;i<p.length;i++){const a=p[(i+p.length-1)%p.length],b=p[i],c=p[(i+1)%p.length];if(cross(a,b,c)<=1e-9)continue;if(p.some(v=>v!==a&&v!==b&&v!==c&&cross(a,b,v)>=-1e-9&&cross(b,c,v)>=-1e-9&&cross(c,a,v)>=-1e-9))continue;out.push([a,b,c]);p.splice(i,1);found=true;break;}if(!found)return [];}out.push(p);return out;}
export function polygonOverlap(a,b){return triangles(a).some(x=>triangles(b).some(y=>convexOverlap(x,y)));}
